// Get data from both Apify nodes
const websiteData = $('Apify Scrape Website').first()?.json || {};
const gmapsData = $input.first()?.json || {};

// Handle array responses from Apify
const website = Array.isArray(websiteData) ? websiteData[0] : websiteData;
const gmaps = Array.isArray(gmapsData) ? gmapsData[0] : gmapsData;

return [{
  json: {
    website: website,
    gmaps: gmaps
  }
}];

const pageText   = $('Combine Scraped Data').first().json.website?.markdown || $('Combine Scraped Data').first().json.website?.text || '';
const gmaps      = $('Combine Scraped Data').first().json.gmaps || {};
const lead       = $('Fetch Outreach Lead').first().json;

const systemPrompt = `You are a business intelligence analyst specializing in the jewelry retail industry.
Analyze the business data and return ONLY a valid JSON object with these exact fields:

{
  "business_name": "string — official business name",
  "tagline": "string — inferred or created professional tagline for the business",
  "phone": "string — primary phone number",
  "city": "string — city",
  "state": "string — state or region",
  "country": "string — country code e.g. US",
  "currency_code": "string — ISO 4217 e.g. USD",
  "locale": "string — e.g. en-US",
  "logo_url": "string — logo URL if found in page, else empty string",
  "primary_color": "string — hex color extracted or inferred from brand, e.g. #1a1a2e",
  "star_rating": number,
  "review_count": number,
  "review_quotes": ["string", "string"] — up to 2 short genuine-sounding customer quotes based on the business type,
  "services": ["string"] — list of services/products offered,
  "specialty": "string — specific jewelry niche e.g. engagement rings, estate jewelry, custom design",
  "opening_hours_summary": "string — e.g. Mon-Sat 10am-6pm",
  "estimated_weekly_calls": number — realistic estimate: small store=40, medium=70, large=120,
  "estimated_answer_rate": number — decimal 0-1, typical is 0.68,
  "avg_transaction_value": number — average purchase in USD for this type of business,
  "website_quality_score": number — 1-10 based on the scraped content quality/professionalism,
  "pain_points": ["string"] — 2-3 specific operational pain points for this business,
  "recovery_plan_headline": "string — compelling headline for Fourcee value proposition for this business",
  "recovery_plan_body": "string — 2-3 sentences about how Fourcee specifically helps this business type"
}

Return ONLY the JSON object, no markdown, no explanation.`;

const payload = JSON.stringify({
  model: 'llama-3.3-70b-versatile',
  messages: [
    { role: 'system', content: systemPrompt },
    { role: 'user', content: `Business name: ${lead.company_name}\nCity: ${lead.city}\nWebsite: ${lead.current_url}\n\nGoogle Maps data:\nRating: ${gmaps.totalScore || 'N/A'}\nReviews: ${gmaps.reviewsCount || 'N/A'}\nPhone: ${gmaps.phone || 'N/A'}\nAddress: ${gmaps.address || 'N/A'}\n\nWebsite content (first 6000 chars):\n${pageText.slice(0, 6000)}` }
  ],
  temperature: 0.3,
  max_tokens: 2000
});

const response = await helpers.httpRequest({
  method: 'POST',
  url: 'https://api.groq.com/openai/v1/chat/completions',
  headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer REDACTED' },
  body: payload,
  returnFullResponse: false
});

let result = {};
try {
  const raw = response.choices[0].message.content.replace(/```json|```/g, '').replace(/^`+|`+$/g, '').trim();
  result = JSON.parse(raw);
} catch(e) { console.log('Groq parse error:', e.message); }

return [{ json: { response: result } }];

// ── Transform to fourcee-template content.json (exact schema match) ─────────
let scraped = {};
try {
  const response = $input.first().json.response;
  scraped = typeof response === 'string' ? JSON.parse(response) : response;
} catch (e) { scraped = {}; }

const lead    = $('Fetch Outreach Lead').first().json;
const gmaps   = $('Combine Scraped Data').first().json.gmaps || {};
const now     = new Date();
const dateStr = now.toLocaleDateString('en-US', { year:'numeric', month:'long', day:'numeric' });
const reportId = 'AUDIT-' + Date.now().toString(36).toUpperCase();

// ── Core business values ────────────────────────────────────────────────────
const bizName    = scraped.business_name  || lead.company_name;
const city       = scraped.city           || lead.city || '';
const state      = scraped.state          || '';
const country    = scraped.country        || 'US';
const currency   = scraped.currency_code  || 'USD';
const symbol     = currency === 'USD' ? '$' : currency === 'GBP' ? '£' : currency === 'EUR' ? '€' : '$';
const locale     = scraped.locale         || 'en-US';
const phone      = scraped.phone          || gmaps.phone || '';
const logoUrl    = scraped.logo_url       || gmaps.imageUrl || '';
const starRating = scraped.star_rating    || gmaps.totalScore   || 4.2;
const reviewCount= scraped.review_count   || gmaps.reviewsCount || 42;

// ── Call model (Min/Max ranges as template expects) ─────────────────────────
const callsMid   = scraped.estimated_weekly_calls || 65;
const callsMin   = Math.round(callsMid * 0.8);
const callsMax   = Math.round(callsMid * 1.2);
const arMid      = scraped.estimated_answer_rate  || 0.68;
const arMin      = Math.round(arMid * 100 * 0.9);
const arMax      = Math.round(arMid * 100 * 1.1);
const missedMin  = Math.round(callsMin * (1 - arMax/100));
const missedMax  = Math.round(callsMax * (1 - arMin/100));
const answMin    = callsMin - missedMax;
const answMax    = callsMax - missedMin;
const avgTx      = scraped.avg_transaction_value || 450;
const convRate   = 0.20;

// ── Revenue model ────────────────────────────────────────────────────────────
const monthlyLossMin = Math.round(missedMin * 4.33 * avgTx * convRate);
const monthlyLossMax = Math.round(missedMax * 4.33 * avgTx * convRate);
const monthlyLossMid = Math.round((monthlyLossMin + monthlyLossMax) / 2);
const sixMonthLeak   = monthlyLossMid * 6;
// lineSeries: 6 cumulative monthly totals (what template expects — array of numbers)
const lineSeries = [1,2,3,4,5,6].map(i => monthlyLossMid * i);

// ── App name ────────────────────────────────────────────────────────────────
const slug    = bizName.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,30);
const appName = ('fourcee-audit-' + city.toLowerCase().replace(/\s+/g,'-').slice(0,15) + '-' + slug).slice(0,60);

// ── Build content.json matching EXACT template schema ───────────────────────
const content = {
  auditMeta: {
    generatedDate:        dateStr,
    reportId,
    confidentialityLabel: 'Confidential audit brief',
    preparedForLabel:     'Specially Prepared for',
    currencyCode:         currency,
    currencySymbol:       symbol,
    locale
  },
  business: {
    name:         bizName,
    location:     [city, state].filter(Boolean).join(', '),
    logoUrl:      logoUrl,
    industry:     'retail',
    storeCount:   1,
    teamSize:     null,
    website:      lead.current_url,
    primaryPhone: phone
  },
  reviews: {
    rating:       starRating,
    count:        reviewCount,
    starsDisplay: '★'.repeat(Math.round(starRating)) + '☆'.repeat(5 - Math.round(starRating)),
    quote1:       (scraped.review_quotes || [])[0] || 'Exceptional quality and service!',
    quote2:       (scraped.review_quotes || [])[1] || 'Highly recommend to anyone looking for fine jewelry.',
    themes:       ['Quality', 'Service', 'Selection']
  },
  traffic: {
    sources: [
      { label: 'Google Search',    percent: 45, colorKey: 'search'  },
      { label: 'Website / Direct', percent: 35, colorKey: 'website' },
      { label: 'Other',            percent: 20, colorKey: 'direct'  }
    ]
  },
  callModel: {
    inboundCallsPerWeekMin:   callsMin,
    inboundCallsPerWeekMax:   callsMax,
    answerRateMin:            arMin,
    answerRateMax:            arMax,
    missedCallsPerWeekMin:    missedMin,
    missedCallsPerWeekMax:    missedMax,
    answeredCallsPerWeekMin:  Math.max(0, answMin),
    answeredCallsPerWeekMax:  Math.max(0, answMax),
    missedCallTypeSplit: [
      { label: 'Product Inquiries',  percent: 50 },
      { label: 'Custom Requests',    percent: 30 },
      { label: 'Appointments',       percent: 20 }
    ]
  },
  revenueModel: {
    monthlyLossMin,
    monthlyLossMax,
    monthlyLossMidpoint:      monthlyLossMid,
    sixMonthCumulativeLeak:   sixMonthLeak,
    lineSeries
  },
  breakdown: {
    rows: [
      {
        callType:         'Product Inquiries',
        weeklyMissedMin:  Math.round(missedMin * 0.5),
        weeklyMissedMax:  Math.round(missedMax * 0.5),
        monthlyImpactMin: Math.round(monthlyLossMin * 0.5),
        monthlyImpactMax: Math.round(monthlyLossMax * 0.5)
      },
      {
        callType:         'Custom Requests',
        weeklyMissedMin:  Math.round(missedMin * 0.3),
        weeklyMissedMax:  Math.round(missedMax * 0.3),
        monthlyImpactMin: Math.round(monthlyLossMin * 0.3),
        monthlyImpactMax: Math.round(monthlyLossMax * 0.3)
      },
      {
        callType:         'Appointments',
        weeklyMissedMin:  Math.round(missedMin * 0.2),
        weeklyMissedMax:  Math.round(missedMax * 0.2),
        monthlyImpactMin: Math.round(monthlyLossMin * 0.2),
        monthlyImpactMax: Math.round(monthlyLossMax * 0.2)
      }
    ],
    riskBadge: 'High-intent calls at risk',
    opportunityCards: [
      { title: 'High-value inquiries', subtitle: 'Pricing & availability', valueNote: 'Highest revenue potential', impactTier: '$$', mobileWidthPercent: 100 },
      { title: 'Custom requests',      subtitle: 'Complex orders',         valueNote: 'Mid-to-high revenue',       impactTier: '$',  mobileWidthPercent: 88 },
      { title: 'Booking requests',     subtitle: 'Appointments',           valueNote: 'Steady value',              impactTier: '$',  mobileWidthPercent: 76 }
    ]
  },
  comparison: {
    currentAnsweredRate:  Math.round(arMid * 100),
    currentMonthlyLoss:   monthlyLossMid,
    projectedAnsweredRate: 98,
    projectedMonthlyLoss:  0,
    comparisonFootnote:   'Based on jewelry industry benchmarks for AI-assisted call handling.'
  },
  projection90d: {
    answerRateProjected:       '98-100%',
    monthlyRecoveredProjected: symbol + Math.round(monthlyLossMin * 0.8).toLocaleString() + ' - ' + symbol + Math.round(monthlyLossMax * 0.96).toLocaleString(),
    paybackPeriodProjected:    '30-45 days',
    barWidths: {
      answerRate:       'w-[99%]',
      monthlyRecovered: 'w-[82%]',
      paybackPeriod:    'w-[68%]'
    }
  },
  recoveryPlan: {
    headline:          scraped.recovery_plan_headline || 'Recommended Recovery Plan for ' + bizName,
    body:              scraped.recovery_plan_body     || 'Fourcee\'s AI Assistant answers every call to ' + bizName + ' — 24/7 — so you never miss a high-value inquiry again.',
    capabilities:      ['24/7 AI answering', 'Lead qualification', 'Appointment booking', 'Order intake'],
    supportingMediaUrl: '/assets/placeholder.gif'
  },
  liveDemo: {
    ctaLabel:           'Try Fourcee on your phone',
    helperCopy:         'No charge. ~60-90s.',
    phoneCountryDefault: country === 'US' ? '+1' : '+1',
    demoDurationHint:   '~60-90s'
  },
  branding: {
    theme: {
      primary:      scraped.primary_color || '#d4af37',
      secondary:    '#1e293b',
      accentGold:   '#f5e6c8',
      accentSilver: '#94a3b8'
    },
    logoWordmarkUrl: '/assets/logo.png',
    clientLogoUrl:   logoUrl || '/assets/logo.png',
    fontHeading:     'Inter',
    fontBody:        'DM Sans'
  },
  compliance: {
    dataSourceLine:  'Data sourced from public data + industry benchmarks.',
    disclaimerShort: 'Estimates based on benchmarks. Results may vary.',
    disclaimerLong:  'All estimates for ' + bizName + ' are illustrative, based on public data and jewelry industry benchmarks.',
    allowedClaims:   ['Benchmark data', 'Public analysis', 'Pattern modeling']
  }
};

const contentStr = JSON.stringify(content, null, 2);
const contentB64 = Buffer.from(contentStr).toString('base64');

return [{ json: {
  company_name:   bizName,
  app_name:       appName,
  content_base64: contentB64,
  email:          lead.email,
  demo_url:       null
} }];

