// UPDATED CODE FOR "Push content.json" NODE
// This handles updating the existing content.json file (requires SHA)

const transform = $('Transform to Audit JSON').item.json;
const GITHUB_TOKEN = 'REDACTED';

console.log('=== PUSH CONTENT.JSON WITH SHA ===');
console.log('App Name:', transform.app_name);
console.log('Company Name:', transform.company_name);

// Validate we have the data
if (!transform.app_name) {
  throw new Error('app_name is missing from Transform output');
}

if (!transform.content_base64) {
  throw new Error('content_base64 is missing from Transform output');
}

const url = `https://api.github.com/repos/neurotechnologica/${transform.app_name}/contents/public/content.json`;

// Step 1: Get the current file's SHA
console.log('Step 1: Getting existing file SHA...');
let sha = null;

try {
  const getResponse = await helpers.httpRequest({
    method: 'GET',
    url: url,
    headers: {
      'Accept': 'application/vnd.github+json',
      'Authorization': `Bearer ${GITHUB_TOKEN}`
    },
    returnFullResponse: false
  });

  sha = getResponse.sha;
  console.log('Found existing file with SHA:', sha);

} catch (error) {
  console.log('File does not exist yet (this is OK for new repos)');
}

// Step 2: Push the file (with SHA if it exists)
console.log('Step 2: Pushing content.json...');

const body = {
  message: `Add audit data for ${transform.company_name}`,
  content: transform.content_base64
};

// Add SHA if file exists
if (sha) {
  body.sha = sha;
  console.log('Including SHA for update');
} else {
  console.log('No SHA needed (creating new file)');
}

try {
  const response = await helpers.httpRequest({
    method: 'PUT',
    url: url,
    headers: {
      'Accept': 'application/vnd.github+json',
      'Authorization': `Bearer ${GITHUB_TOKEN}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(body),
    returnFullResponse: true
  });

  console.log('=== PUSH SUCCESS ===');
  console.log('HTTP Status:', response.statusCode);
  console.log('File Path:', response.body.content?.path);
  console.log('File Size:', response.body.content?.size);
  console.log('New SHA:', response.body.content?.sha);
  console.log('Commit Message:', response.body.commit?.message);

  return [{ json: response.body }];

} catch (error) {
  console.log('=== PUSH ERROR ===');
  console.log('Error message:', error.message);
  console.log('Error status:', error.statusCode);
  console.log('Error details:', JSON.stringify(error.response?.body, null, 2));

  throw new Error(`GitHub API Error: ${error.message}`);
}

const lead = $('Transform to Audit JSON').first().json;
const fetchedLead = $('Fetch Outreach Lead').first().json;
const demoUrl = $('Get Vercel Production URL').first().json.production_url;
const companyName = lead.company_name;
const email = fetchedLead.email;
const fromEmail = fetchedLead.outreach_email_used || 'emily@fourceelabs.com';

// Map fromEmail to senderIndex for SMTP routing
const senderMap = {
  'emily@fourceelabs.com': 0,
  'emily@thefourcee.com': 1,
  'emily@fourceeapp.com': 2,
  'emily@fourceehq.com': 3
};
const senderIndex = senderMap[fromEmail] ?? 0;

const htmlBody = `
<div style="font-family:'Helvetica Neue',Helvetica,Arial,sans-serif;max-width:560px;margin:0 auto;color:#333;line-height:1.7;">
  <p>Hi there,</p>
  <p>Great news — we've put together your personalised business audit for <strong>${companyName}</strong>.</p>
  <p>It shows exactly where your business is leaving money on the table and what a modern digital presence could look like for you.</p>
  <div style="text-align:center;margin:32px 0;">
    <a href="${demoUrl}" style="background:#d4af37;color:#fff;padding:14px 36px;border-radius:6px;text-decoration:none;font-size:16px;font-weight:bold;">View Your Free Audit &rarr;</a>
  </div>
  <p style="font-size:13px;color:#888;">This was prepared specifically for ${companyName} using your public business data.</p>
  <p>Best,<br>Emily<br><strong>Fourcee</strong></p>
</div>`;

return [{
  json: {
    to: email,
    from: fromEmail,
    subject: `Re: Quick note about ${companyName}'s online presence`,
    html: htmlBody,
    demo_url: demoUrl,
    senderIndex
  }
}];

const deploymentId = $('Deploy to Vercel').first().json.id;
const vercelToken = 'REDACTED';

// Poll until deployment is READY (max 3 minutes)
let productionUrl = null;
let attempts = 0;

while (attempts < 18) {
  const res = await helpers.httpRequest({
    method: 'GET',
    url: `https://api.vercel.com/v13/deployments/${deploymentId}`,
    headers: { 'Authorization': `Bearer ${vercelToken}` },
    returnFullResponse: false
  });

  console.log(`Attempt ${attempts + 1}: status = ${res.readyState}`);

  if (res.readyState === 'READY') {
    // Get the shortest alias that ends with .vercel.app (the clean production URL)
    const aliases = res.alias || [];
    const clean = aliases
      .filter(a => a.endsWith('.vercel.app') && !a.includes('projects.vercel.app') && !a.includes('-git-'))
      .sort((a, b) => a.length - b.length);

    productionUrl = clean[0] ? `https://${clean[0]}` : `https://${res.url}`;
    console.log('Production URL:', productionUrl);
    break;
  }

  if (res.readyState === 'ERROR' || res.readyState === 'CANCELED') {
    throw new Error(`Deployment failed with state: ${res.readyState}`);
  }

  // Wait 10 seconds before retrying
  await new Promise(r => setTimeout(r, 10000));
  attempts++;
}

if (!productionUrl) {
  throw new Error('Deployment did not become READY within 3 minutes');
}

return [{
  json: {
    ...($('Transform to Audit JSON').first().json),
    production_url: productionUrl
  }
}];
